
begin;
set local lock_timeout='8s';
set local statement_timeout='60s';
do $import$
declare
 m jsonb := $manifest${"batch":"sail-result-2025-2026-10-28","event":{"id":"4b3dd72f-e963-5f6f-861b-ca29352eb7bc","slug":"yrat-cup-series-5-2025","name":"2025 YRAT Cup Series 5","startDate":"2025-08-30","endDate":"2025-08-31","venue":"Dongtan Bay, Sattahip, Thailand","organizer":"Yacht Racing Association of Thailand","classes":["ILCA 4","ILCA 6","ILCA 7","Optimist"]},"sheet":{"id":"23ddeb06-cd30-5553-bb1e-f6bf059a925d","slug":"yrat-cup-series-5-2025-ilca6","name":"2025 YRAT Cup Series 5 — ILCA 6","boatClass":"ILCA 6","division":"Open","raceCount":6,"totalFleetSize":6,"entryType":"individual","minParticipants":1,"maxParticipants":1},"officialSource":{"url":"https://www.racingrulesofsailing.org/documents/156704","title":"2025 YRAT Cup Series 5 — ILCA 6 Open results","type":"pdf","provisional":false,"publicationStatus":"final","visuallyReviewed":true,"pdfSearch":null},"results":[{"eventKey":"yrat-cup-series-5-2025","sourceDocument":156704,"sourcePage":2,"sourceClass":"ILCA 6","boatClass":"ILCA 6","division":"Open","rank":1,"name":"NOPPASSORN KHUNBOONJAN","sailOrBoardNumber":"THA217427","club":"YRAT","nationality":null,"gender":"F","officialBirthYear":2006,"sourceBirthYear":"2006","grossScore":10.0,"nettScore":7.0,"races":[{"raceNumber":1,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":2,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":3,"score":3.0,"code":null,"discarded":true,"raw":"(3.0)"},{"raceNumber":4,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":5,"score":2.0,"code":null,"discarded":false,"raw":"2.0"},{"raceNumber":6,"score":2.0,"code":null,"discarded":false,"raw":"2.0"}],"handicap":false,"sailorId":"d29da64f-723a-45e0-a4d6-57eb7a1b1e82","identityBasis":"Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged.","resultId":"eeb83600-eaca-5843-96a8-9e1f23712467","participants":[{"id":"b6de3c8c-cc2c-56d0-b096-4b8c45d29af3","sailorId":"d29da64f-723a-45e0-a4d6-57eb7a1b1e82","sourceName":"NOPPASSORN KHUNBOONJAN","displayOrder":1,"role":"solo"}],"evidenceNotes":"Official source class: ILCA 6; page 2; source name: NOPPASSORN KHUNBOONJAN; historic sail: THA217427; club: YRAT; year field: 2006. Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged."},{"eventKey":"yrat-cup-series-5-2025","sourceDocument":156704,"sourcePage":2,"sourceClass":"ILCA 6","boatClass":"ILCA 6","division":"Open","rank":2,"name":"Miss Marion Grace Montgomery","sailOrBoardNumber":"THA222660","club":"YRAT/RVYC","nationality":null,"gender":"F","officialBirthYear":2008,"sourceBirthYear":"2008","grossScore":17.0,"nettScore":12.0,"races":[{"raceNumber":1,"score":2.0,"code":null,"discarded":false,"raw":"2.0"},{"raceNumber":2,"score":5.0,"code":null,"discarded":true,"raw":"(5.0)"},{"raceNumber":3,"score":4.0,"code":null,"discarded":false,"raw":"4.0"},{"raceNumber":4,"score":4.0,"code":null,"discarded":false,"raw":"4.0"},{"raceNumber":5,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":6,"score":1.0,"code":null,"discarded":false,"raw":"1.0"}],"handicap":false,"sailorId":"0f33df5e-ca62-502f-a771-b44846d6ac6a","identityBasis":"Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged.","resultId":"f33f7a65-fa89-589d-8d82-fed4af9292bb","participants":[{"id":"f42ee477-b60f-50c3-b810-482947a6a4b3","sailorId":"0f33df5e-ca62-502f-a771-b44846d6ac6a","sourceName":"Miss Marion Grace Montgomery","displayOrder":1,"role":"solo"}],"evidenceNotes":"Official source class: ILCA 6; page 2; source name: Miss Marion Grace Montgomery; historic sail: THA222660; club: YRAT/RVYC; year field: 2008. Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged."},{"eventKey":"yrat-cup-series-5-2025","sourceDocument":156704,"sourcePage":2,"sourceClass":"ILCA 6","boatClass":"ILCA 6","division":"Open","rank":3,"name":"Patcharee Sringam","sailOrBoardNumber":"210250","club":"YRAT","nationality":null,"gender":"F","officialBirthYear":2003,"sourceBirthYear":"2003","grossScore":18.0,"nettScore":13.0,"races":[{"raceNumber":1,"score":3.0,"code":null,"discarded":false,"raw":"3.0"},{"raceNumber":2,"score":2.0,"code":null,"discarded":false,"raw":"2.0"},{"raceNumber":3,"score":2.0,"code":null,"discarded":false,"raw":"2.0"},{"raceNumber":4,"score":2.0,"code":null,"discarded":false,"raw":"2.0"},{"raceNumber":5,"score":4.0,"code":null,"discarded":false,"raw":"4.0"},{"raceNumber":6,"score":5.0,"code":null,"discarded":true,"raw":"(5.0)"}],"handicap":false,"sailorId":"7dbdb651-0954-5059-be8f-8ea0e85883dd","identityBasis":"Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged.","resultId":"80f2148c-4b19-58ec-bab3-13e270751da7","participants":[{"id":"932a1c60-8ed5-5098-b433-d37960eccd12","sailorId":"7dbdb651-0954-5059-be8f-8ea0e85883dd","sourceName":"Patcharee Sringam","displayOrder":1,"role":"solo"}],"evidenceNotes":"Official source class: ILCA 6; page 2; source name: Patcharee Sringam; historic sail: 210250; club: YRAT; year field: 2003. Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged."},{"eventKey":"yrat-cup-series-5-2025","sourceDocument":156704,"sourcePage":2,"sourceClass":"ILCA 6","boatClass":"ILCA 6","division":"Open","rank":4,"name":"Thorfun Boonnak","sailOrBoardNumber":"THA222660","club":"YRAT","nationality":null,"gender":"F","officialBirthYear":2005,"sourceBirthYear":"2005","grossScore":20.0,"nettScore":15.0,"races":[{"raceNumber":1,"score":5.0,"code":null,"discarded":true,"raw":"(5.0)"},{"raceNumber":2,"score":4.0,"code":null,"discarded":false,"raw":"4.0"},{"raceNumber":3,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":4,"score":3.0,"code":null,"discarded":false,"raw":"3.0"},{"raceNumber":5,"score":3.0,"code":null,"discarded":false,"raw":"3.0"},{"raceNumber":6,"score":4.0,"code":null,"discarded":false,"raw":"4.0"}],"handicap":false,"sailorId":"5cfe0b90-2ff3-5777-9fdd-9d29aeb5883c","identityBasis":"Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged.","resultId":"4df767dc-f298-5ff1-b92d-df7b101e5dd4","participants":[{"id":"d6f1c1fa-4f16-5fff-9893-f7b3bf525d16","sailorId":"5cfe0b90-2ff3-5777-9fdd-9d29aeb5883c","sourceName":"Thorfun Boonnak","displayOrder":1,"role":"solo"}],"evidenceNotes":"Official source class: ILCA 6; page 2; source name: Thorfun Boonnak; historic sail: THA222660; club: YRAT; year field: 2005. Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged."},{"eventKey":"yrat-cup-series-5-2025","sourceDocument":156704,"sourcePage":2,"sourceClass":"ILCA 6","boatClass":"ILCA 6","division":"Open","rank":5,"name":"Puttaraksa imraksa","sailOrBoardNumber":"220236","club":"YRAT","nationality":null,"gender":"F","officialBirthYear":2006,"sourceBirthYear":"2006","grossScore":25.0,"nettScore":20.0,"races":[{"raceNumber":1,"score":4.0,"code":null,"discarded":false,"raw":"4.0"},{"raceNumber":2,"score":3.0,"code":null,"discarded":false,"raw":"3.0"},{"raceNumber":3,"score":5.0,"code":null,"discarded":true,"raw":"(5.0)"},{"raceNumber":4,"score":5.0,"code":null,"discarded":false,"raw":"5.0"},{"raceNumber":5,"score":5.0,"code":null,"discarded":false,"raw":"5.0"},{"raceNumber":6,"score":3.0,"code":null,"discarded":false,"raw":"3.0"}],"handicap":false,"sailorId":"5191c60e-3586-5a0d-b103-5512d9e35440","identityBasis":"Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged.","resultId":"b2f999bf-5102-5e39-b3c7-0810fc95b786","participants":[{"id":"18a73e62-0f26-5095-93ac-fece1f33ed16","sailorId":"5191c60e-3586-5a0d-b103-5512d9e35440","sourceName":"Puttaraksa imraksa","displayOrder":1,"role":"solo"}],"evidenceNotes":"Official source class: ILCA 6; page 2; source name: Puttaraksa imraksa; historic sail: 220236; club: YRAT; year field: 2006. Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged."},{"eventKey":"yrat-cup-series-5-2025","sourceDocument":156704,"sourcePage":2,"sourceClass":"ILCA 6","boatClass":"ILCA 6","division":"Open","rank":6,"name":"NICHAWAN NITHITHONGSAKUL","sailOrBoardNumber":"1","club":"YRAT","nationality":null,"gender":"F","officialBirthYear":2008,"sourceBirthYear":"2008","grossScore":36.0,"nettScore":30.0,"races":[{"raceNumber":1,"score":6.0,"code":null,"discarded":true,"raw":"(6.0)"},{"raceNumber":2,"score":6.0,"code":null,"discarded":false,"raw":"6.0"},{"raceNumber":3,"score":6.0,"code":null,"discarded":false,"raw":"6.0"},{"raceNumber":4,"score":6.0,"code":null,"discarded":false,"raw":"6.0"},{"raceNumber":5,"score":6.0,"code":null,"discarded":false,"raw":"6.0"},{"raceNumber":6,"score":6.0,"code":null,"discarded":false,"raw":"6.0"}],"handicap":false,"sailorId":"846c6c12-eed5-58e1-bd90-9fba7fe01007","identityBasis":"Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged.","resultId":"09471353-522d-5ffd-9b3d-1fbe3f0b3c39","participants":[{"id":"563cade1-8ccf-567f-b964-700de4eeb8be","sailorId":"846c6c12-eed5-58e1-bd90-9fba7fe01007","sourceName":"NICHAWAN NITHITHONGSAKUL","displayOrder":1,"role":"solo"}],"evidenceNotes":"Official source class: ILCA 6; page 2; source name: NICHAWAN NITHITHONGSAKUL; historic sail: 1; club: YRAT; year field: 2008. Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged."}],"importedEntryCount":6,"deferredEntryCount":0,"publicSummary":"Final organiser results. Official fleet ranks, scoring codes and discards retained.","pendingEntries":[],"profilePreflight":[{"id":"d29da64f-723a-45e0-a4d6-57eb7a1b1e82","club":"Yacht Racing Association of Thailand","name":"Noppassorn Khunboonjan","gender":"F","handle":"noppassorn-khunboonjan-69917e4211","birthYear":2006,"sailNumber":"217427","nationality":"THA","sailNumberIlca4":null},{"id":"5191c60e-3586-5a0d-b103-5512d9e35440","club":"YRAT","name":"Puttaraksa Imraksa","gender":"F","handle":"puttaraksa-imraksa-sr26-5191c6","birthYear":2006,"sailNumber":"","nationality":"THA","sailNumberIlca4":null},{"id":"846c6c12-eed5-58e1-bd90-9fba7fe01007","club":"YRAT","name":"Nichawan Nithithongsakul","gender":"F","handle":"nichawan-nithithongsakul-sr26-846c6c","birthYear":2008,"sailNumber":"","nationality":"THA","sailNumberIlca4":null},{"id":"5cfe0b90-2ff3-5777-9fdd-9d29aeb5883c","club":"YRAT","name":"Thorfun Boonnak","gender":"F","handle":"thorfun-boonnak-sr26-5cfe0b","birthYear":2005,"sailNumber":"","nationality":"THA","sailNumberIlca4":null},{"id":"0f33df5e-ca62-502f-a771-b44846d6ac6a","club":"YRAT/RVYC","name":"Marion Grace Montgomery","gender":"F","handle":"marion-grace-montgomery-sr26-0f33df","birthYear":2008,"sailNumber":"","nationality":"THA","sailNumberIlca4":null},{"id":"7dbdb651-0954-5059-be8f-8ea0e85883dd","club":"YRAT","name":"Patcharee Sringam","gender":"F","handle":"patcharee-sringam-sr26-7dbdb6","birthYear":2003,"sailNumber":"","nationality":"THA","sailNumberIlca4":null}],"newProfiles":[],"identityReview":{"method":"Unique exact full names and reviewed aliases; close-name and abbreviated identities held."}}$manifest$::jsonb;
 p jsonb; r jsonb; part jsonb; race jsonb;
 e regatta_events%rowtype; s regattas%rowtype;
 replay boolean; expected_count int; race_count int; rid uuid; sid uuid;
 before_profiles text; after_profiles text;
begin
 perform pg_advisory_xact_lock(hashtextextended(m#>>'{sheet,slug}',0));
 expected_count:=jsonb_array_length(m->'results');race_count:=(m#>>'{sheet,raceCount}')::int;
 if expected_count<>(m->>'importedEntryCount')::int or expected_count>(m#>>'{sheet,totalFleetSize}')::int or
   (select count(distinct x->>'sailorId') from jsonb_array_elements(m->'results') x)<>expected_count
   then raise exception 'Manifest identity/count invalid'; end if;
 select exists(select 1 from admin_change_log where source=m->>'batch' and action='results.import_official_sailresult2025' and entity_id=(m#>>'{sheet,id}')::uuid) into replay;
 perform 1 from sailors where id in(select (x->>'id')::uuid from jsonb_array_elements(m->'profilePreflight') x) order by id for update;
 select md5(jsonb_agg(to_jsonb(a) order by a.id)::text) into before_profiles from sailors a where id in(select (x->>'id')::uuid from jsonb_array_elements(m->'profilePreflight') x);
 for p in select value from jsonb_array_elements(m->'profilePreflight') loop
  if not exists(select 1 from sailors a where a.id=(p->>'id')::uuid and jsonb_build_object('id',a.id,'name',a.name,'handle',a.handle,'sailNumber',a.sail_number,'sailNumberIlca4',a.sail_number_ilca4,'nationality',a.nationality,'gender',a.gender,'club',a.club,'birthYear',extract(year from a.dob)::int)=p)
   then raise exception 'Existing profile changed since identity review: %',p->>'name'; end if;
 end loop;
 if not replay then
  if exists(select 1 from regattas where slug=m#>>'{sheet,slug}' or id=(m#>>'{sheet,id}')::uuid or (event_id=(m#>>'{event,id}')::uuid and boat_class=m#>>'{sheet,boatClass}' and division=m#>>'{sheet,division}'))
   then raise exception 'Sheet exists without matching audit; review before overwriting'; end if;
  for p in select value from jsonb_array_elements(m->'newProfiles') loop
   if exists(select 1 from sailors where (lower(name)=lower(p->>'name') or handle=p->>'handle') and id<>(p->>'id')::uuid)
    then raise exception 'New profile already has a candidate: %',p->>'name'; end if;
   if exists(select 1 from sailors a where a.id=(p->>'id')::uuid and (a.name<>p->>'name' or a.handle<>p->>'handle' or a.nationality is distinct from p->>'nationality' or a.gender is distinct from p->>'gender'))
    then raise exception 'Conflicting profile UUID: %',p->>'name'; end if;
   insert into sailors(id,name,handle,sail_number,sail_number_ilca4,club,nationality,gender)
    values((p->>'id')::uuid,p->>'name',p->>'handle',p->>'sailNumber',p->>'sailNumberIlca4',p->>'club',p->>'nationality',p->>'gender') on conflict(id) do nothing;
  end loop;
  if exists(select 1 from regatta_events where slug=m#>>'{event,slug}' and id<>(m#>>'{event,id}')::uuid) then raise exception 'Event slug has conflicting identity'; end if;
  if exists(select 1 from regatta_events where id=(m#>>'{event,id}')::uuid and (slug<>m#>>'{event,slug}' or name<>m#>>'{event,name}' or start_date<>(m#>>'{event,startDate}')::date or end_date<>(m#>>'{event,endDate}')::date)) then raise exception 'Parent event changed since review'; end if;
  insert into regatta_events(id,name,slug,start_date,end_date,venue,organizer,classes,counts_for_ranking,schedule_summary,scoring_rules)
   values((m#>>'{event,id}')::uuid,m#>>'{event,name}',m#>>'{event,slug}',(m#>>'{event,startDate}')::date,(m#>>'{event,endDate}')::date,m#>>'{event,venue}',m#>>'{event,organizer}',m#>'{event,classes}',false,'Official class results imported. See each fleet sheet for publication status and pending identity reviews.','Low points; race counts and discards as published on each official class sheet.') on conflict(id) do nothing;
  update regatta_events set classes=(select jsonb_agg(distinct value order by value) from jsonb_array_elements(coalesce(classes,'[]'::jsonb)||(m#>'{event,classes}'))) where id=(m#>>'{event,id}')::uuid;
  insert into regattas(id,name,slug,event_id,date,end_date,total_fleet_size,division,race_count,geography,boat_class,entry_type,min_participants,max_participants,counts_for_ranking,venue,organizer,status,official_results_url,official_results_source_name,reviewed_at,schedule_notes)
   values((m#>>'{sheet,id}')::uuid,m#>>'{sheet,name}',m#>>'{sheet,slug}',(m#>>'{event,id}')::uuid,(m#>>'{event,startDate}')::date,(m#>>'{event,endDate}')::date,(m#>>'{sheet,totalFleetSize}')::int,m#>>'{sheet,division}',race_count,'THA',m#>>'{sheet,boatClass}',m#>>'{sheet,entryType}',(m#>>'{sheet,minParticipants}')::int,(m#>>'{sheet,maxParticipants}')::int,false,m#>>'{event,venue}',m#>>'{event,organizer}','published',m#>>'{officialSource,url}',m#>>'{officialSource,title}',now(),m->>'publicSummary');
  for r in select value from jsonb_array_elements(m->'results') loop
   rid:=(r->>'resultId')::uuid;sid:=(r->>'sailorId')::uuid;
   insert into regatta_results(id,sailor_id,regatta_id,entry_label,entry_sail_number,entry_type,rank,total_score,nett_score,gender,nationality,birth_year,is_dns,is_overseas_commitment,official_url,evidence_url,evidence_name,evidence_type,evidence_notes,verification_status,verified_at)
    values(rid,sid,(m#>>'{sheet,id}')::uuid,r->>'name',r->>'sailOrBoardNumber',m#>>'{sheet,entryType}',(r->>'rank')::int,(r->>'grossScore')::real,(r->>'nettScore')::real,r->>'gender',r->>'nationality',(r->>'officialBirthYear')::int,false,false,m#>>'{officialSource,url}',m#>>'{officialSource,url}',m#>>'{officialSource,title}',m#>>'{officialSource,type}',r->>'evidenceNotes','verified',now());
   for part in select value from jsonb_array_elements(r->'participants') loop
    insert into regatta_result_participants(id,regatta_result_id,sailor_id,source_name,display_order,role,match_status,ranking_credit)
     values((part->>'id')::uuid,rid,(part->>'sailorId')::uuid,part->>'sourceName',(part->>'displayOrder')::int,part->>'role','matched',false);
   end loop;
   insert into regatta_race_results(regatta_result_id,race_number,score,scoring_code,discarded,raw_value)
    select rid,(x->>'raceNumber')::int,(x->>'score')::real,x->>'code',(x->>'discarded')::boolean,x->>'raw' from jsonb_array_elements(r->'races') x;
  end loop;
  insert into admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source)
   values('results.import_official_sailresult2025','regatta',(m#>>'{sheet,id}')::uuid,m#>>'{sheet,name}','Imported reviewed 2025 official race scores, discards, penalties and evidence. Ambiguous identities deferred per user instruction; existing profiles unchanged.',jsonb_build_object('officialSource',m->'officialSource','expectedEntries',expected_count,'expectedRaceScores',expected_count*race_count,'officialFleetSize',m#>'{sheet,totalFleetSize}','deferredEntries',m->'pendingEntries','newProfileIds',(select jsonb_agg(x->>'id') from jsonb_array_elements(m->'newProfiles') x),'identityReview',m->'identityReview','singaporeRankingCredit',false),m->>'batch');
 end if;
 select * into e from regatta_events where id=(m#>>'{event,id}')::uuid;
 if e.id is null or e.slug<>m#>>'{event,slug}' or e.name<>m#>>'{event,name}' or e.start_date<>(m#>>'{event,startDate}')::date or e.end_date<>(m#>>'{event,endDate}')::date or not (e.classes @> (m#>'{event,classes}')) or e.counts_for_ranking
  then raise exception 'Parent event verification failed'; end if;
 select * into s from regattas where id=(m#>>'{sheet,id}')::uuid;
 if s.id is null or s.slug<>m#>>'{sheet,slug}' or s.event_id<>e.id or s.race_count<>race_count or s.total_fleet_size<>(m#>>'{sheet,totalFleetSize}')::int or s.boat_class<>m#>>'{sheet,boatClass}' or s.division<>m#>>'{sheet,division}' or s.entry_type<>m#>>'{sheet,entryType}' or s.status<>'published' or s.counts_for_ranking or s.official_results_url<>m#>>'{officialSource,url}' or s.schedule_notes<>m->>'publicSummary'
  then raise exception 'Final sheet metadata verification failed'; end if;
 if (select count(*) from regatta_results where regatta_id=s.id)<>expected_count or
    (select count(*) from regatta_race_results a join regatta_results b on b.id=a.regatta_result_id where b.regatta_id=s.id)<>expected_count*race_count
  then raise exception 'Final result/race inventory differs'; end if;
 for r in select value from jsonb_array_elements(m->'results') loop
  rid:=(r->>'resultId')::uuid;
  if not exists(select 1 from regatta_results where id=rid and regatta_id=s.id and sailor_id=(r->>'sailorId')::uuid and entry_label=r->>'name' and entry_sail_number=r->>'sailOrBoardNumber' and entry_type=m#>>'{sheet,entryType}' and rank=(r->>'rank')::int and abs(total_score-(r->>'grossScore')::real)<.001 and abs(nett_score-(r->>'nettScore')::real)<.001 and nationality is not distinct from r->>'nationality' and gender is not distinct from r->>'gender' and birth_year is not distinct from (r->>'officialBirthYear')::int and evidence_url=m#>>'{officialSource,url}' and official_url=m#>>'{officialSource,url}' and evidence_type=m#>>'{officialSource,type}' and evidence_notes=r->>'evidenceNotes' and verification_status='verified' and not is_dns and not is_overseas_commitment)
   then raise exception 'Result/evidence differs: %',r->>'name'; end if;
  if (select count(*) from regatta_result_participants where regatta_result_id=rid)<>jsonb_array_length(r->'participants')
   then raise exception 'Participant count differs'; end if;
  for part in select value from jsonb_array_elements(r->'participants') loop
   if not exists(select 1 from regatta_result_participants where id=(part->>'id')::uuid and regatta_result_id=rid and sailor_id=(part->>'sailorId')::uuid and source_name=part->>'sourceName' and display_order=(part->>'displayOrder')::int and role=part->>'role' and match_status='matched' and not ranking_credit)
    then raise exception 'Participant differs: %',part->>'sourceName'; end if;
  end loop;
  if not exists(select 1 from regatta_race_results where regatta_result_id=rid group by regatta_result_id having count(*)=race_count and abs(sum(score)-(r->>'grossScore')::real)<.001 and abs(sum(score) filter(where not discarded)-(r->>'nettScore')::real)<.001 and count(*) filter(where discarded)=(select count(*) from jsonb_array_elements(r->'races') z where (z->>'discarded')::boolean))
   then raise exception 'Row reconciliation failed: %',r->>'name'; end if;
  for race in select value from jsonb_array_elements(r->'races') loop
   if not exists(select 1 from regatta_race_results where regatta_result_id=rid and race_number=(race->>'raceNumber')::int and score=(race->>'score')::real and scoring_code is not distinct from race->>'code' and discarded=(race->>'discarded')::boolean and raw_value=race->>'raw')
    then raise exception 'Race/code/discard differs'; end if;
  end loop;
 end loop;
 select md5(jsonb_agg(to_jsonb(a) order by a.id)::text) into after_profiles from sailors a where id in(select (x->>'id')::uuid from jsonb_array_elements(m->'profilePreflight') x);
 if before_profiles is distinct from after_profiles then raise exception 'Existing profiles changed unexpectedly'; end if;
end
$import$;
commit;
